-- Standalone clean VM package for the captured BlackHub prototype tree.
-- This module does not execute the recovered program. Call build(environment)
-- to obtain its entry closure, then call that closure only when desired.

local module = {}

local function makeRuntime()
    local runtime = {}
    local emptyResults = {}
    local function inert() return nil end

    runtime[2] = bit32.bxor
    runtime[3] = 9007199254740992
    runtime[9] = 4503599627370496
    runtime[15] = 2147483648
    runtime[19] = getfenv
    runtime[21] = coroutine.yield
    runtime[22] = {}
    runtime[23] = function(first, last, values)
        if first > last then return end
        return values[first], runtime[23](first + 1, last, values)
    end
    runtime[26] = function(last, values, first)
        first = first or 1
        last = last or #values
        return table.unpack(values, first, last)
    end
    runtime[28] = {}
    runtime[29] = inert
    runtime[30] = 127399
    runtime[31] = emptyResults
    runtime[32] = table.move
    runtime[34] = bit32.band
    runtime[35] = inert
    runtime[36] = 4294967296
    runtime[37] = buffer.create(0)
    runtime[39] = table.create
    runtime[40] = inert
    runtime[41] = setfenv
    runtime[43] = inert
    runtime[44] = function() return nil end
    runtime[45] = {}
    runtime[46] = function() return nil end
    runtime[47] = function() return nil end
    runtime[48] = function() return nil end
    runtime[49] = function() return nil end
    runtime[50] = function() return nil end
    runtime[51] = coroutine.wrap
    runtime[52] = function() return nil end
    runtime[53] = function() return nil end
    runtime[54] = bit32.rshift
    runtime[55] = function() return nil end
    runtime[56] = function() return nil end
    runtime[57] = function(...)
        local count = select("#", ...)
        if count == 0 then return 0, emptyResults end
        return count, {...}
    end

    return runtime
end

local function getBits(value, firstBit, lastBit)
    local shifted = value / (2 ^ (firstBit - 1))
    if lastBit ~= nil then
        local width = lastBit - firstBit + 1
        local remainder = shifted % (2 ^ width)
        return remainder - (remainder % 1)
    end
    return (value % (2 ^ firstBit) >= 2 ^ (firstBit - 1)) and 1 or 0
end

local function makeNativeOverrides(byPath)
    return {
        -- Whole zero-argument tamper callback. Its return value is discarded.
        [byPath["0.6.279.6.2"]] = function()
            return nil
        end,
        [byPath["0.6.279.6.2.6.20.6.7"]] = function(_, left, right)
            return bit32.bxor(left, right)
        end,
        [byPath["0.6.279.6.2.6.20.6.20"]] = function(_, value, firstBit, lastBit)
            return getBits(value, firstBit, lastBit)
        end,
        [byPath["0.6.279.6.2.6.20.6.22"]] = function(upvalues)
            local readU32 = upvalues[0]
            local readBits = upvalues[1]
            local high = readU32()
            local low = readU32()
            local mantissa = readBits(high, 1, 20) * 4294967296 + low
            local exponent = readBits(high, 21, 31)
            local sign = readBits(high, 32) == 0 and -1 or 1
            if exponent == 0 then
                if mantissa == 0 then return sign * 0 end
                return sign * 2 ^ -1022 * (mantissa / 4503599627370496)
            end
            if exponent == 2047 then
                if mantissa == 0 then return sign * math.huge end
                return 0 / 0
            end
            return sign * 2 ^ (exponent - 1023) * (1 + mantissa / 4503599627370496)
        end,
        -- Bogus billion-iteration decode sink used only by the tamper path.
        [byPath["0.6.279.6.2.6.20.6.23"]] = function()
            return nil
        end,
    }
end

function module.build(environment, traceCallback)
    environment = environment or getfenv(2)
    local runtime = makeRuntime()
    local vm = {
        A = factories.A,
        s = factories.s,
        __TRACE = traceCallback,
    }
    vm.__NATIVE_PROTOTYPES = makeNativeOverrides(bundle.byPath)

    local constructor = makeConstructor(vm, runtime)
    runtime[58] = constructor
    local entry = constructor(bundle.root, environment)
    setfenv(entry, environment)

    return entry, {
        root = bundle.root,
        byPath = bundle.byPath,
        runtime = runtime,
        vm = vm,
        constructor = constructor,
    }
end

local environment
if type(getgenv) == "function" then
    environment = getgenv()
else
    environment = getfenv()
end

local entry = module.build(environment)
return entry()
